const lead = $json.body || $json;
const names = { atencion: 'Atención al cliente', ventas: 'Ventas', admin: 'Administración', rrhh: 'Recursos humanos', marketing: 'Marketing', direccion: 'Dirección' };
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const a = lead.analysis;
const rows = (a?.areas || []).map((x) => `<tr><td style="padding:10px 0;border-top:1px solid #e5e7eb;width:140px;color:#0066ff;font-weight:600;vertical-align:top">${esc(names[x.id] || x.id)}</td><td style="padding:10px 0;border-top:1px solid #e5e7eb"><strong>${esc(x.title)}</strong><br><span style="color:#4b5563">${esc(x.description)}</span><br><span style="color:#6b7280;font-size:13px">Potencial ${x.score}/100 · ≈ ${x.hoursPerWeek} h/semana</span></td></tr>`).join('');
const total = (a?.areas || []).reduce((s, x) => s + (x.hoursPerWeek || 0), 0);
const domain = String(lead.url || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0];
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#111827;line-height:1.6"><h1 style="font-size:22px">Tu mapa de automatización${a ? ' · ' + esc(a.company) : ''}</h1>${a ? `<p style="color:#4b5563">${esc(a.summary)}</p><p><strong>${total} horas a la semana</strong> de trabajo repetitivo que podrían automatizarse.</p>` : ''}<table style="width:100%;border-collapse:collapse;font-size:15px">${rows}</table><p style="margin-top:24px">Si quieres que revisemos juntos por dónde empezar, reserva 30 minutos: <a href="https://cal.com/alpa-digital-studio/30min" style="color:#0066ff">cal.com/alpa-digital-studio/30min</a></p><p style="color:#6b7280;font-size:13px;margin-top:32px">Alpa Digital · Automatización e IA para pymes · info@alpa.digital</p></div>`;
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(lead.email || ''))) throw new Error('Email no válido');
return [{ json: { email: lead.email, url: lead.url, sector: lead.sector || a?.sector || 'sin determinar', domain, html, source: a?.source || 'sin análisis' } }];
